package caddyfile

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func writeFile(t *testing.T, path, content string) {
	t.Helper()
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
		t.Fatal(err)
	}
}

func parseAllWithFile(filename, input string) ([]ServerBlock, error) {
	tokens, err := allTokens(filename, []byte(input))
	if err != nil {
		return nil, err
	}
	p := parser{
		Dispenser: NewDispenser(tokens),
		importGraph: importGraph{
			nodes: make(map[string]struct{}),
			edges: make(adjacency),
		},
	}
	return p.parseAll()
}

// A file matched both directly and through a symlink alias in one glob
// must be expanded only once.
func TestScratchGlobDedupSymlink(t *testing.T) {
	dir := t.TempDir()
	writeFile(t, filepath.Join(dir, "conf.d", "a.conf"), "host-a\n")
	writeFile(t, filepath.Join(dir, "conf.d", "b.conf"), "host-b\n")
	if err := os.Symlink(filepath.Join(dir, "conf.d", "a.conf"), filepath.Join(dir, "conf.d", "alias.conf")); err != nil {
		t.Fatal(err)
	}
	main := filepath.Join(dir, "Caddyfile")
	blocks, err := parseAllWithFile(main, "import "+filepath.Join(dir, "conf.d", "*"))
	if err != nil {
		t.Fatal(err)
	}
	if len(blocks) != 2 {
		t.Fatalf("expected 2 blocks (deduped), got %d: %v", len(blocks), blocks)
	}
	// sorted by canonical path: a.conf before b.conf
	if blocks[0].Keys[0].Text != "host-a" || blocks[1].Keys[0].Text != "host-b" {
		t.Fatalf("unexpected order: %v, %v", blocks[0].Keys[0].Text, blocks[1].Keys[0].Text)
	}
}

// Explicit duplicate imports must NOT be deduped.
func TestScratchExplicitDuplicateImport(t *testing.T) {
	dir := t.TempDir()
	f := filepath.Join(dir, "a.conf")
	writeFile(t, f, "host-a\n")
	main := filepath.Join(dir, "Caddyfile")
	blocks, err := parseAllWithFile(main, "import "+f+"\nimport "+f)
	if err != nil {
		t.Fatal(err)
	}
	if len(blocks) != 2 {
		t.Fatalf("expected explicit duplicate import to expand twice, got %d blocks", len(blocks))
	}
}

// Relative imports resolve against the real directory of the declaring
// file, even when it was reached through a symlink.
func TestScratchRelativeImportThroughSymlink(t *testing.T) {
	dir := t.TempDir()
	realDir := filepath.Join(dir, "real")
	writeFile(t, filepath.Join(realDir, "main.conf"), "import sub/child.conf\n")
	writeFile(t, filepath.Join(realDir, "sub", "child.conf"), "host-child\n")
	linkDir := filepath.Join(dir, "link")
	if err := os.Symlink(realDir, linkDir); err != nil {
		t.Fatal(err)
	}
	blocks, err := parseAllWithFile(filepath.Join(linkDir, "main.conf"), "import main.conf")
	if err != nil {
		t.Fatal(err)
	}
	if len(blocks) != 1 || blocks[0].Keys[0].Text != "host-child" {
		t.Fatalf("unexpected result: %+v", blocks)
	}
}

// A cycle formed through a symlink alias must be detected and the error
// must name the files in the cycle.
func TestScratchCycleViaSymlinkAlias(t *testing.T) {
	dir := t.TempDir()
	writeFile(t, filepath.Join(dir, "a.conf"), "import b.conf\n")
	writeFile(t, filepath.Join(dir, "b.conf"), "import link-to-a\n")
	if err := os.Symlink(filepath.Join(dir, "a.conf"), filepath.Join(dir, "link-to-a")); err != nil {
		t.Fatal(err)
	}
	_, err := parseAllWithFile(filepath.Join(dir, "Caddyfile"), "import a.conf")
	if err == nil {
		t.Fatal("expected cycle error")
	}
	if !strings.Contains(err.Error(), "cycle") {
		t.Fatalf("error should mention cycle: %v", err)
	}
	aCanon, _ := filepath.EvalSymlinks(filepath.Join(dir, "a.conf"))
	bCanon, _ := filepath.EvalSymlinks(filepath.Join(dir, "b.conf"))
	if !strings.Contains(err.Error(), aCanon) || !strings.Contains(err.Error(), bCanon) {
		t.Fatalf("error should name files in cycle: %v", err)
	}
	t.Logf("cycle error: %v", err)
}

// Diamond imports (same file imported by two different files) are not a cycle.
func TestScratchDiamondNotCycle(t *testing.T) {
	dir := t.TempDir()
	writeFile(t, filepath.Join(dir, "shared.conf"), "respond ok\n")
	writeFile(t, filepath.Join(dir, "a.conf"), "host-a\nimport shared.conf\n")
	writeFile(t, filepath.Join(dir, "b.conf"), "host-b\nimport shared.conf\n")
	_, err := parseAllWithFile(filepath.Join(dir, "Caddyfile"), "import a.conf\nimport b.conf")
	if err != nil {
		t.Fatalf("diamond import should not be a cycle: %v", err)
	}
}

// Self-import through a ".." path spelling must be detected as a cycle.
func TestScratchSelfImportViaDotDot(t *testing.T) {
	dir := t.TempDir()
	sub := filepath.Join(dir, "sub")
	writeFile(t, filepath.Join(sub, "self.conf"), "import ../sub/self.conf\n")
	_, err := parseAllWithFile(filepath.Join(dir, "Caddyfile"), "import sub/self.conf")
	if err == nil {
		t.Fatal("expected cycle error for self import via ..")
	}
	t.Logf("self-import error: %v", err)
}

// Main file importing itself through a symlinked path to itself.
func TestScratchMainCycleViaAlias(t *testing.T) {
	dir := t.TempDir()
	main := filepath.Join(dir, "Caddyfile")
	writeFile(t, main, "import alias\n")
	if err := os.Symlink(main, filepath.Join(dir, "alias")); err != nil {
		t.Fatal(err)
	}
	_, err := parseAllWithFile(main, "import alias")
	if err == nil {
		t.Fatal("expected cycle error for main file importing itself via alias")
	}
	t.Logf("alias cycle error: %v", err)
}

// Determinism: repeated parses give identical results.
func TestScratchDeterminism(t *testing.T) {
	dir := t.TempDir()
	writeFile(t, filepath.Join(dir, "conf.d", "c.conf"), "host-c\n")
	writeFile(t, filepath.Join(dir, "conf.d", "a.conf"), "host-a\n")
	writeFile(t, filepath.Join(dir, "conf.d", "b.conf"), "host-b\n")
	input := "import " + filepath.Join(dir, "conf.d", "*")
	var first []ServerBlock
	for i := 0; i < 5; i++ {
		blocks, err := parseAllWithFile(filepath.Join(dir, "Caddyfile"), input)
		if err != nil {
			t.Fatal(err)
		}
		if i == 0 {
			first = blocks
			continue
		}
		if len(blocks) != len(first) {
			t.Fatalf("iteration %d: different block count", i)
		}
		for j := range blocks {
			if blocks[j].Keys[0].Text != first[j].Keys[0].Text {
				t.Fatalf("iteration %d: different order", i)
			}
		}
	}
	if first[0].Keys[0].Text != "host-a" || first[1].Keys[0].Text != "host-b" || first[2].Keys[0].Text != "host-c" {
		t.Fatalf("unexpected order: %v", first)
	}
}

