	writeFile(t, filepath.Join(dir, "conf.d", "c.conf"), "host-c\n")
	writeFile(t, filepath.Join(dir, "conf.d", "a.conf"), "host-a\n")
	writeFile(t, filepath.Join(dir, "conf.d", "b.conf"), "host-b\n")
	input := "import " + filepath.Join(dir, "conf.d", "*")
